        to_account = request.values.get('to')
        amount = request.values.get('amount')

        # --------------------------------------------
        conn = sqlite3.connect('vulnerable_app.db')
        cursor = conn.cursor()
        cursor.execute("UPDATE accounts SET balance = balance - ? WHERE username = ?", (amount, from_account))
